(function(){
  "use strict";
  setTimeout(function(){document.documentElement.classList.remove("anim");},1800);

  // Protección básica anti-copia
  document.addEventListener("contextmenu",function(e){e.preventDefault();});
  document.addEventListener("dragstart",function(e){e.preventDefault();});
  document.addEventListener("keydown",function(e){
    if(e.key==="F12"||((e.ctrlKey||e.metaKey)&&e.shiftKey&&["I","J","C"].indexOf(e.key.toUpperCase())!==-1)||((e.ctrlKey||e.metaKey)&&["U","S"].indexOf(e.key.toUpperCase())!==-1)){
      e.preventDefault();
    }
  });

  var toast=document.getElementById("toast"),t;
  function say(msg){
    toast.textContent=msg;toast.classList.add("on");
    clearTimeout(t);t=setTimeout(function(){toast.classList.remove("on")},2100);
  }

  // Compartir tarjeta
  var share=document.getElementById("shareBtn");
  if(share){
    share.addEventListener("click",function(){
      var data={title:"Jerry Osorno | Jerry Systems",
                text:"La Tecnología a tu alcance — mi tarjeta digital:",
                url:"https://jerrysystems.github.io/tarjeta/"};
      if(navigator.share){navigator.share(data).catch(function(){});return;}
      var done=function(){say("Enlace copiado")};
      if(navigator.clipboard&&navigator.clipboard.writeText){
        navigator.clipboard.writeText(data.url).then(done,function(){say(data.url)});
      }else{
        var ta=document.createElement("textarea");ta.value=data.url;
        document.body.appendChild(ta);ta.select();
        try{document.execCommand("copy");done();}catch(e){say(data.url);}
        document.body.removeChild(ta);
      }
    });
  }

  // Copiar datos al mantener presionada una tarjeta de contacto
  var longPress;
  Array.prototype.forEach.call(document.querySelectorAll(".tile small"),function(el){
    var tile=el.closest(".tile");
    function start(){
      longPress=setTimeout(function(){
        var txt=el.textContent.trim();
        if(navigator.clipboard){navigator.clipboard.writeText(txt).then(function(){
          say("Copiado: "+txt);},{});
        }
        if(navigator.vibrate){navigator.vibrate(12);}
      },480);
    }
    function stop(){clearTimeout(longPress);}
    ["touchstart","mousedown"].forEach(function(e){tile.addEventListener(e,start,{passive:true});});
    ["touchend","touchcancel","mouseup","mouseleave","scroll"].forEach(function(e){
      tile.addEventListener(e,stop,{passive:true});});
  });

  // Decodificación dinámica del portafolio de desarrollos
  var _0x9a="";
  function decodePortfolio(b64){
    try{
      var bin=atob(b64);
      var bytes=new Uint8Array(bin.length);
      for(var i=0;i<bin.length;i++){bytes[i]=bin.charCodeAt(i);}
      return JSON.parse(new TextDecoder("utf-8").decode(bytes));
    }catch(e){return [];}
  }

  var grid=document.getElementById("devGrid");
  var audioBar=document.getElementById("audioBar");
  var audioEl=document.getElementById("demoAudio");
  var items=decodePortfolio(_0x9a);

  if(grid&&items.length){
    var frag=document.createDocumentFragment();
    items.forEach(function(it){
      var card=document.createElement("a");
      card.className="dev-card"+(it.featured?" featured":"");
      card.href=it.u;
      if(it.type==="audio"){
        card.addEventListener("click",function(ev){
          ev.preventDefault();
          audioBar.classList.add("active");
          audioEl.src=it.u;
          audioEl.play().catch(function(){});
          audioBar.scrollIntoView({behavior:"smooth",block:"nearest"});
          say("Reproduciendo muestra musical");
        });
      }else if(it.ext||/^(https?:\/\/wa\.me|mailto:|tel:)/i.test(it.u)){
        // Enlaces externos (WhatsApp, correo, teléfono) abren app externa / nueva pestaña
        card.target="_blank";
        card.rel="noopener noreferrer";
      }else{
        // Enlaces web se abren en la misma pestaña y aseguran historial #desarrollos para volver con "Atrás"
        card.addEventListener("click",function(){
          if(window.location.hash!=="#desarrollos"&&history.replaceState){
            history.replaceState({devOpen:true},"","#desarrollos");
          }
        });
      }

      var thumb=document.createElement("div");
      thumb.className="dev-thumb";
      var img=document.createElement("img");
      img.src=it.img;
      img.alt=it.t;
      img.loading="lazy";
      thumb.appendChild(img);

      if(it.b){
        var badge=document.createElement("span");
        badge.className="dev-badge";
        badge.textContent=it.b;
        thumb.appendChild(badge);
      }

      var body=document.createElement("div");
      body.className="dev-card-body";
      var h3=document.createElement("h3");
      h3.className="dev-card-title";
      h3.textContent=it.t;
      body.appendChild(h3);

      var cta=document.createElement("span");
      cta.className=it.featured?"dev-cta-pill":"dev-card-cta";
      cta.innerHTML=(it.featured
        ?'<svg width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.3" stroke-linecap="round" stroke-linejoin="round"><path d="M21 11.5a8.4 8.4 0 0 1-12.5 7.4L3.5 20.5l1.6-4.9A8.4 8.4 0 1 1 21 11.5z"/></svg>'
        :'<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.2" stroke-linecap="round" stroke-linejoin="round"><path d="M7 17L17 7M7 7h10v10"/></svg>')
        +it.cta;
      body.appendChild(cta);

      card.appendChild(thumb);
      card.appendChild(body);
      frag.appendChild(card);
    });
    grid.appendChild(frag);
  }

  // Control de apertura/cierre de pantalla "Algunos de Nuestros Desarrollos" con soporte de historial nativo
  var openBtn=document.getElementById("openDevBtn");
  var closeBtn=document.getElementById("closeDevBtn");
  var screen=document.getElementById("devScreen");

  function showDevUI(){
    screen.classList.add("open");
    screen.setAttribute("aria-hidden","false");
    document.body.classList.add("modal-open");
  }
  function hideDevUI(){
    screen.classList.remove("open");
    screen.setAttribute("aria-hidden","true");
    document.body.classList.remove("modal-open");
    if(audioEl&&!audioEl.paused){audioEl.pause();}
  }

  function openDev(){
    showDevUI();
    if(window.location.hash!=="#desarrollos"&&history.pushState){
      history.pushState({devOpen:true},"","#desarrollos");
    }
  }
  function closeDev(){
    if(window.location.hash==="#desarrollos"&&history.state&&history.state.devOpen){
      history.back();
    }else{
      hideDevUI();
      if(history.replaceState){history.replaceState(null,"",window.location.pathname);}
    }
  }

  if(openBtn)openBtn.addEventListener("click",openDev);
  if(closeBtn)closeBtn.addEventListener("click",closeDev);
  window.addEventListener("popstate",function(){
    if(window.location.hash==="#desarrollos"){showDevUI();}
    else{hideDevUI();}
  });
  window.addEventListener("pageshow",function(){
    if(window.location.hash==="#desarrollos"){showDevUI();}
  });
  document.addEventListener("keydown",function(e){
    if(e.key==="Escape"&&screen.classList.contains("open"))closeDev();
  });
  if(window.location.hash==="#desarrollos")showDevUI();
})();
